&\sum_{t=0}^{19}x_{GT,t}\le 1, \qquad
\sum_{t=0}^{19}x_{CC,t}\le 1, \qquad
\sum_{t=0}^{19}x_{PSA,t}\le 1,\\
&\sum_{t=0}^{19}x_{HEN_k,t}\le 1 \;\;(k=1,2,3),\\[2pt]
&\sum_{\tau\le t}x_{HEN_k,\tau}\;\ge\;x_{HEN_{k+1},t}
\qquad\forall t,\;k=1,2,\\[2pt]
&0\le f_{CO2}\le\sum_{t=0}^{19}x_{CC,t},\\[2pt]
&Q_{MeOH,t}= 
\begin{cases}
Y_{0}\bigl(1+0.025\,f_{CO2}-0.001\,f_{CO2}^{2}\bigr), & 
