&E_t=5\sum_{\tau\le t}x_{GT,\tau}
\;+\;0.5\;\bigl(0.10\,Q_{RM,t}\bigr)\,0.9\,x_{PSA,t}\;\bigl[\text{MWh}\bigr],\\[2pt]
&U_t=15\!\times\!10^{6}\;-\;\sum_{k=1}^{3}\Delta U_{k}\,x_{HEN_k,t},\\[2pt]
&x_{i,t}\in\{0,1\}\;\;\forall i\in\{GT,CC,PSA,HEN_{1},HEN_{2},HEN_{3}\},\;t=0,\dots,19,\\
&f_{CO2}\in[0,1].
\end{aligned}
}
