\[
r=k_3\,
\frac{C_s\,K_{\rm H_2O}P_{\rm H_2O}}
{1+K_{\rm CO}P_{\rm CO}+K_{\rm H_2O}P_{\rm H_2O}}\;
\frac{C_s}{1+K_{\rm CO}P_{\rm CO}+K_{\rm H_2O}P_{\rm H_2O}}
