\end{aligned}
\]

*External surface area*

\[
A_{\text{ext}} = 4\pi R_{\text{out}}^{2}
               = 4\pi (5.0\times10^{-6})^{2}
               = \pi \times10^{-10}\ \text{cm}^{2}
               \approx 3.14\times10^{-10}\ \text{cm}^{2}.
\]

*Shell volume*

\[
\begin{aligned}
V_{\text{shell}} &= \frac{4}{3}\pi\!\left(R_{\text{out}}^{3}-R_{\text{in}}^{3}\right)\\
&= \frac{4}{3}\pi\!\left[(5.0\times10^{-6})^{3}-(4.0\times10^{-6})^{3}\right]\\
&\approx 2.56\times10^{-16}\ \text{cm}^{3}.
