\alpha\ge0,\;\beta\ge0,\;\gamma\ge0,\;\delta\ge0,\;\eta\ge0,\;\theta\ge0.
\\[6pt]
&\textbf{KKT conditions for a minimiser }(\alpha^*,\beta^*,\gamma^*,\delta^*,\eta^*,\theta^*)\\
&\text{Introduce Lagrange multipliers } 
\lambda_\alpha,\lambda_\beta,\lambda_\gamma,
\lambda_\delta,\lambda_\eta,\lambda_\theta\ge0.\\
&\text{Lagrangian: } 
\mathcal L=
J(\alpha,\beta,\gamma,\delta,\eta,\theta)
+\lambda_\alpha(-\alpha)+\lambda_\beta(-\beta)+\lambda_\gamma(-\gamma)
+\lambda_\delta(-\delta)+\lambda_\eta(-\eta)+\lambda_\theta(-\theta).\\[4pt]
&\textbf{(i) Primal feasibility: } 
\alpha,\beta,\gamma,\delta,\eta,\theta\ge0.\\
&\textbf{(ii) Dual feasibility: } 
\lambda_\alpha,\lambda_\beta,\lambda_\gamma,
\lambda_\delta,\lambda_\eta,\lambda_\theta\ge0.\\
&\textbf{(iii) Stationarity: } 
\frac{\partial\mathcal L}{\partial\alpha}= 
\frac{\partial J}{\partial\alpha}-\lambda_\alpha=0,\;
\frac{\partial\mathcal L}{\partial\beta}= 
\frac{\partial J}{\partial\beta}-\lambda_\beta=0,\;
\ldots,\;
\frac{\partial\mathcal L}{\partial\theta}= 
\frac{\partial J}{\partial\theta}-\lambda_\theta=0,\\[4pt]
&\qquad\text{with }
\frac{\partial J}{\partial\alpha}
=-2\sum_{i,j}\int_{0}^{T_{ij}}
\bigl[c_{\text{out}}^{\;{\rm exp}}-\hat c_{\text{out}}\bigr]\,
\frac{\partial\hat c_{\text{out}}}{\partial\alpha}\,dt,
\;\text{etc.}\\
&\textbf{(iv) Complementary slackness: } 
\lambda_\alpha\,\alpha=0,\;
\lambda_\beta\,\beta=0,\;
\lambda_\gamma\,\gamma=0,\;
\lambda_\delta\,\delta=0,\;
\lambda_\eta\,\eta=0,\;
\lambda_\theta\,\theta=0.
\end{aligned}
}
